	private RoomRepository $rooms;private AgentRepository $agents;private JobRepository $jobs;private MessageRepository $messages;private int $user=0,$outsider=0,$room=0,$agent=0;private string $prefix='';
	public function run():void{$this->prefix='phase8-'.gmdate('YmdHis').'-'.wp_generate_password(5,false,false);$this->rooms=new RoomRepository();$this->agents=new AgentRepository();$this->jobs=new JobRepository();$this->messages=new MessageRepository();$this->setup();try{$this->schema();echo"PASS phase8_schema\n";$this->presence();echo"PASS phase8_human_presence\n";$this->participation();echo"PASS phase8_agent_participation\n";$this->contracts();echo"PASS phase8_contracts\n";}finally{$this->cleanup();}}
	private function setup():void{$this->user=(int)wp_insert_user(array('user_login'=>$this->prefix,'user_pass'=>wp_generate_password(20),'user_email'=>$this->prefix.'@example.test','display_name'=>'Phase 8 Owner','role'=>'subscriber'));$this->outsider=(int)wp_insert_user(array('user_login'=>$this->prefix.'-out','user_pass'=>wp_generate_password(20),'user_email'=>$this->prefix.'-out@example.test','display_name'=>'Phase 8 Outsider','role'=>'subscriber'));foreach(array($this->user,$this->outsider)as$id){get_user_by('id',$id)->add_cap('acl_ar_use_rooms');}get_user_by('id',$this->user)->add_cap('acl_ar_manage_own_rooms');wp_set_current_user($this->user);$this->room=$this->rooms->create(array('title'=>$this->prefix,'slug'=>$this->prefix,'owner_user_id'=>$this->user,'type'=>'private','visibility'=>'private','agent_reply_mode'=>'auto','max_agents_per_turn'=>3));$this->agent=$this->agents->create(array('name'=>$this->prefix.' Agent','slug'=>$this->prefix.'-agent','provider_route'=>'fake','model'=>'fake','system_prompt'=>'Fixture','enabled'=>1));$this->rooms->assign_agents($this->room,array($this->agent));}
	private function schema():void{global$wpdb;$before=$wpdb->get_col("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='".esc_sql(DB_NAME)."' AND TABLE_NAME LIKE 'wp_acl_ar_%' ORDER BY TABLE_NAME");\ACL\AgentRooms\Installer::install();\ACL\AgentRooms\Installer::install();$after=$wpdb->get_col("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='".esc_sql(DB_NAME)."' AND TABLE_NAME LIKE 'wp_acl_ar_%' ORDER BY TABLE_NAME");$this->assert_same('1.5.6',ACL_AR_VERSION,'Version.');$this->assert_same('1.4.1',ACL_AR_DB_VERSION,'DB version.');$this->assert_same('1.4.1',(string)get_option('acl_ar_db_version'),'Stored version.');$this->assert_same($before,$after,'Repeat migration.');$table=$wpdb->prefix.'acl_ar_room_presence_sessions';$this->assert_same($table,(string)$wpdb->get_var($wpdb->prepare('SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$table)),'Session table.');$columns=$wpdb->get_col($wpdb->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$table));foreach(array('id','room_id','user_id','session_hash','visibility_state','activity_state','last_seen_at','last_active_at','expires_at','created_at','updated_at')as$c){$this->assert_true(in_array($c,$columns,true),'Missing '.$c);}$indexes=$wpdb->get_col($wpdb->prepare('SELECT DISTINCT INDEX_NAME FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$table));foreach(array('PRIMARY','room_user_session','room_expires_id','room_user_expires','user_updated')as$i){$this->assert_true(in_array($i,$indexes,true),'Missing '.$i);}$ra=$wpdb->get_col($wpdb->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$wpdb->prefix.'acl_ar_room_agents'));foreach(array('participation_state','auto_muted','state_updated_at')as$c){$this->assert_true(in_array($c,$ra,true),'Assignment '.$c);}$rp=$wpdb->get_col($wpdb->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s',DB_NAME,$wpdb->prefix.'acl_ar_room_presence'));foreach(array('last_event_id','expires_at')as$c){$this->assert_true(in_array($c,$rp,true),'Projection '.$c);}$p=$this->rooms->get_assignment($this->room,$this->agent);$this->assert_same('active',$p['participation_state'],'Migration active.');$this->assert_same('0',(string)$p['auto_muted'],'Migration unmuted.');}
	private function presence():void{global$wpdb;$service=new PresenceSessionService();$hash=$service->session_hash($this->room,$this->user,'tab-one-secure-id');$this->assert_same(64,strlen($hash),'Hash length.');$this->assert_same($hash,$service->session_hash($this->room,$this->user,'tab-one-secure-id'),'Hash deterministic.');$this->assert_true($hash!==$service->session_hash($this->room+1,$this->user,'tab-one-secure-id'),'Hash room scope.');$this->assert_wp_error($service->heartbeat($this->room,$this->user,'short','visible','active'),'Short ID.');$active=$service->heartbeat($this->room,$this->user,'tab-one-secure-id','visible','active');$this->assert_same('active',$active['state'],'Active.');$service->heartbeat($this->room,$this->user,'tab-two-secure-id','hidden','idle');$this->assert_same('active',(new PresenceAggregationService())->aggregate_user($this->room,$this->user)['state'],'Visible wins.');$sessions=(new PresenceSessionRepository())->active_for_user($this->room,$this->user);$this->assert_same(2,count($sessions),'Two tabs.');$json=wp_json_encode($sessions);$this->assert_true(false===strpos($json,'tab-one-secure-id'),'Raw ID stored.');$this->assert_true(false===strpos($json,'tab-two-secure-id'),'Raw ID two stored.');$wpdb->update($wpdb->prefix.'acl_ar_room_presence_sessions',array('activity_state'=>'idle','last_active_at'=>gmdate('Y-m-d H:i:s',time()-120)),array('session_hash'=>$hash));$this->assert_same('idle',(new PresenceAggregationService())->aggregate_user($this->room,$this->user)['state'],'Idle wins hidden.');$service->leave($this->room,$this->user,'tab-one-secure-id');$this->assert_same('away',(new PresenceAggregationService())->aggregate_user($this->room,$this->user)['state'],'Away.');$before=count((new PresenceSessionRepository())->active_for_user($this->room,$this->user));$service->leave($this->room,$this->outsider,'tab-two-secure-id');$this->assert_same($before,count((new PresenceSessionRepository())->active_for_user($this->room,$this->user)),'Cross user delete.');$service->leave($this->room,$this->user,'tab-two-secure-id');$this->assert_same('offline',(new PresenceAggregationService())->aggregate_user($this->room,$this->user)['state'],'Offline.');$controller=new PresenceController($this->rooms,new AccessService($this->rooms));$controller->register_routes();$routes=rest_get_server()->get_routes();foreach(array('/acl-agent-rooms/v1/rooms/(?P<id>\d+)/participants','/acl-agent-rooms/v1/rooms/(?P<id>\d+)/presence/heartbeat','/acl-agent-rooms/v1/rooms/(?P<id>\d+)/presence/session','/acl-agent-rooms/v1/rooms/(?P<id>\d+)/agents/(?P<agent_id>\d+)/participation')as$route){$this->assert_true(isset($routes[$route]),'Route '.$route);}$request=new WP_REST_Request('POST','/');$request->set_param('id',$this->room);$this->assert_wp_error($controller->write_permissions($request),'Nonce required.');wp_set_current_user($this->outsider);$read=new WP_REST_Request('GET','/');$read->set_param('id',$this->room);$this->assert_wp_error($controller->read_permissions($read),'Private denial.');wp_set_current_user($this->user);$get=new WP_REST_Request('GET','/');$get->set_param('id',$this->room);$data=$controller->participants($get)->get_data();$serialized=wp_json_encode($data);$this->assert_true(isset($data['participants'],$data['summary'],$data['sync']),'Envelope.');foreach(array('session_id','session_hash','user_email','user_login','@example.test')as$secret){$this->assert_true(false===stripos($serialized,$secret),'Leak '.$secret);}}
	private function participation():void{global$wpdb;$trigger=$this->messages->create(array('room_id'=>$this->room,'sender_type'=>'user','sender_user_id'=>$this->user,'content'=>'fixture'));$pending=$this->jobs->create($this->room,(int)$trigger,$this->agent,JobRepository::request_key('p8',$this->room,(int)$trigger,$this->agent));$retry=$this->jobs->create($this->room,(int)$trigger,$this->agent,JobRepository::request_key('p8retry',$this->room,(int)$trigger,$this->agent));$this->jobs->fail((int)$retry,'retry','retry','retry',true,1);$service=new AgentParticipationService($this->rooms,$this->jobs);$paused=$service->change($this->room,$this->agent,'paused',false,$this->user,'p8-pause-request');$this->assert_same('paused',$paused['participation']['state'],'Paused.');$this->assert_same('canceled',$this->jobs->find((int)$pending)['status'],'Pending canceled.');$this->assert_same('canceled',$this->jobs->find((int)$retry)['status'],'Retry canceled.');$this->assert_true(!$this->jobs->find((int)$pending)['retryable'],'Canceled terminal.');$this->assert_wp_error($service->enforce($this->room,$this->agent,'explicit'),'Explicit paused.');$this->assert_same(array(),$service->filter_targets($this->room,$this->rooms->get_agents($this->room),true),'Auto paused.');$events=(new EventRepository())->scan_room_after($this->room,0,500);$changes=array_values(array_filter($events,static fn($e)=>'presence_change'===$e['event_type']));$this->assert_same(1,count($changes),'One event.');$this->assert_same(null,$changes[0]['content']?:null,'No content.');$service->change($this->room,$this->agent,'paused',false,$this->user,'p8-pause-request');$changes=array_values(array_filter((new EventRepository())->scan_room_after($this->room,0,500),static fn($e)=>'presence_change'===$e['event_type']));$this->assert_same(1,count($changes),'Idempotent event.');$service->change($this->room,$this->agent,'active',true,$this->user,'p8-mute-request');$this->assert_true(is_wp_error($service->enforce($this->room,$this->agent,'automatic')),'Muted auto.');$this->assert_same(true,$service->enforce($this->room,$this->agent,'explicit'),'Muted explicit.');$service->change($this->room,$this->agent,'active',false,$this->user,'p8-unmute-request');$this->assert_same(1,count($service->filter_targets($this->room,$this->rooms->get_agents($this->room),true)),'Unmute auto.');$late=$this->jobs->create($this->room,(int)$trigger,$this->agent,JobRepository::request_key('p8late',$this->room,(int)$trigger,$this->agent));$service->change($this->room,$this->agent,'paused',false,$this->user,'p8-late-pause');$fake=new ACL_AR_FakeSwitchboard();$runtime=new AgentRuntime($this->jobs,$this->rooms,$this->agents,$this->messages,null,$fake);$this->assert_wp_error($runtime->run_job((int)$late),'Late pause blocked.');$this->assert_same(0,$fake->calls,'Provider called.');$this->assert_same('canceled',$this->jobs->find((int)$late)['status'],'Late canceled.');$this->assert_same('paused',(new AgentStateReconciler())->reconcile_assignment($this->room,$this->agent),'Paused projection.');$presence=(new PresenceRepository())->find($this->room,'agent',$this->agent);$this->assert_same('paused',$presence['state'],'Projection stored.');$service->change($this->room,$this->agent,'active',false,$this->user,'p8-resume');$this->assert_same('ready',(new AgentStateReconciler())->reconcile_assignment($this->room,$this->agent),'Resume ready.');$this->assert_same('canceled',$this->jobs->find((int)$late)['status'],'Resume no recreate.');}
	private function contracts():void{$root=dirname(__DIR__);$files=array('includes/Services/AgentRuntime.php'=>'switchboard->send','includes/Services/AgentParticipationService.php'=>'cancel_for_assignment','includes/Services/PresenceSessionService.php'=>"hash('sha256'",'includes/Services/PresenceAggregationService.php'=>"'active':'idle'",'includes/Rest/PresenceController.php'=>'Cache-Control','assets/js/room/presence.js'=>'sessionStorage','assets/js/room/presence.js'=>'getRandomValues','assets/js/room/presence.js'=>'setTimeout','assets/js/room/agent-participation.js'=>'confirmPause','assets/js/room/member-list.js'=>'Recently active','assets/js/room/member-list.js'=>'Auto replies muted','assets/js/room.js'=>'ACLARRoomPresence','uninstall.php'=>'acl_ar_room_presence_sessions');foreach($files as$file=>$needle){$source=preg_replace('/\s+/','',(string)file_get_contents($root.'/'.$file));$contract=preg_replace('/\s+/','',$needle);$this->assert_true(false!==strpos($source,$contract),'Contract '.$needle);}$forbidden=array('package.json','composer.json');foreach($forbidden as$file){$this->assert_true(!file_exists($root.'/'.$file),'Forbidden '.$file);}$this->assert_true(false===strpos((string)file_get_contents($root.'/assets/js/room/presence.js'),'localStorage'),'Presence localStorage.');$this->assert_true(false===stripos((string)file_get_contents($root.'/includes/Rest/PresenceController.php'),'email'),'Email DTO.');}
